107	/**
108	 * Moves the claim to the asked status, refusing a change its current status does not allow,
109	 * and refusing to let the user who opened it settle it. Opening records who opened it. Settling
110	 * fixes the claim's due at its person's grade's rate in force on the claim's date — or, while a statement binds it, at
111	 * the figure it was bound to; without a figure its due stays live.
112	 */
113	public class ApplyClaimStatus {
114	    public void apply(@Val ClaimStatus status, @Val Claim claim, ClaimRepository repository,
115	            PersonRepository people, RateRepository rates, @Val ChangedBy by, Out<ClaimNumber> audited) throws BadRequestException {
116	        ClaimStatus from = claim.getStatus();
117	        if (!from.canBecome(status)) {
118	            throw new BadRequestException("A " + from + " claim cannot become " + status);
119	        }
120	        if (status == ClaimStatus.SETTLED && by.name().equals(claim.getOpenedBy())) {
121	            throw new BadRequestException("The user who opened a claim cannot settle it");
122	        }
123	        Integer had = claim.getNumber();
124	        claim.setStatus(status);
125	        if (status == ClaimStatus.VOID) {
126	            claim.setNumber(null);
127	        }
128	        if (status == ClaimStatus.OPEN) {
129	            claim.setOpenedBy(by.name());
130	        }
131	        if (status == ClaimStatus.SETTLED) {
132	            claim.setSettledDue(dueNow(claim, people, rates));
133	        }
134	        if (!repository.updateStatus(claim, from)) {
135	            throw new BadRequestException("The claim was changed by someone else; reload the sheet");
136	        }
137	        if (status == ClaimStatus.OPEN) {
138	            // Numbered only once the claim is surely moving, so a refused open uses up no number.
139	            claim.setNumber(repository.nextNumber(claim.getSheetId()));
140	            repository.updateStatus(claim, status);
141	        }
142	        audited.set(new ClaimNumber(status == ClaimStatus.VOID ? had : claim.getNumber()));
143	    }
144	
145	    /** The figure a statement bound the claim to, else the claim's amount times its person's grade's rate on the claim's date, rounded half to even; null when there is no rate. */
146	    private static BigDecimal dueNow(Claim claim, PersonRepository people, RateRepository rates) {
147	        if (claim.isStated()) {
148	            return claim.getStatedDue();
149	        }
150	        Person person = people.find(claim.getSheetId(), claim.getPersonId());
151	        BigDecimal rate = person == null ? null : rates.find(claim.getSheetId(), person.getGrade(), claim.getDate());
152	        return rate == null ? null
153	                : claim.getAmount().multiply(rate).movePointLeft(2).setScale(2, RoundingMode.HALF_EVEN);
154	    }
