443	/** A claim's status: DRAFT → OPEN → SETTLED, and a DRAFT or OPEN claim may become VOID. */
444	public enum ClaimStatus {
445	    DRAFT, OPEN, SETTLED, VOID;
446	
447	    /** Whether a claim in this status may move to {@code next}. */
448	    public boolean canBecome(ClaimStatus next) {
449	        return switch (next) {
450	            case OPEN -> this == DRAFT;
451	            case SETTLED -> this == OPEN;
452	            case VOID -> this == DRAFT || this == OPEN;
453	            case DRAFT -> false;
454	        };
455	    }
456	
457	    /** Whether a claim in this status counts toward claimed, due and every total. */
458	    public boolean counts() {
459	        return this == OPEN || this == SETTLED;
460	    }
461	}
