1519	
1520	/**
1521	 * Takes the person's statement on the sheet's today: records their due-total, binds each of their counting claims
1522	 * to the figure it has now, and unbinds the rest. A claim's figure is its settled due when it has one, else the
1523	 * figure its last statement bound it to, else its amount times its person's grade's rate in force on the claim's
1524	 * date (rounded half to even; none without a rate). The due-total is the counting claims' figures added up; n/a
1525	 * (null) when the grade has no rate today and no counting claim keeps a settled or bound figure.
1526	 */
1527	public class TakeStatement {
1528	    public void take(@Val Person person, ClaimRepository claims, RateRepository rates, SheetRepository sheets,
1529	            StatementRepository statements, Out<Statement> taken) {
1530	        String sheetId = person.getSheetId();
1531	        LocalDate today = sheets.today(sheetId);
1532	        List<Claim> mine = claims.listOf(sheetId, person.getId());
1533	        BigDecimal sum = BigDecimal.ZERO.setScale(2);
1534	        boolean kept = false;
1535	        int counted = 0;
1536	        for (Claim c : mine) {
1537	            if (!c.getStatus().counts()) {
1538	                claims.bind(c.getId(), false, null);
1539	                continue;
1540	            }
1541	            counted++;
1542	            kept |= c.getSettledDue() != null || (c.isStated() && c.getStatedDue() != null);
1543	            BigDecimal figure = figure(c, person, rates);
1544	            if (figure != null) {
1545	                sum = sum.add(figure);
1546	            }
1547	            claims.bind(c.getId(), true, figure);
1548	        }
1549	        BigDecimal dueTotal = kept || rates.find(sheetId, person.getGrade(), today) != null ? sum : null;
1550	        statements.insert(sheetId, person.getId(), dueTotal, today);
1551	        person.setStatements(new Statements(person.getStatements().count() + 1, dueTotal, today));
1552	        taken.set(new Statement(dueTotal, counted));
1553	    }
1554	
1555	    private static BigDecimal figure(Claim claim, Person person, RateRepository rates) {
1556	        if (claim.getSettledDue() != null) {
1557	            return claim.getSettledDue();
1558	        }
1559	        if (claim.isStated()) {
1560	            return claim.getStatedDue();
1561	        }
1562	        BigDecimal rate = rates.find(claim.getSheetId(), person.getGrade(), claim.getDate());
1563	        return rate == null ? null
1564	                : claim.getAmount().multiply(rate).movePointLeft(2).setScale(2, RoundingMode.HALF_EVEN);
1565	    }
1566	}
